using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]     // base 5%, discount 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]     // 50.00 enters the +1 band
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]   // 6%, discount 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]   // 200.00 enters the +3 band
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]    // 10% exactly
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]   // 9%, discount 449.91 -> 449
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]   // 9+1 = 10
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12 capped at 10
    [InlineData(LoyaltyTier.Green, 1, 1)]             // discount rounds down to 0
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var payable = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, payable);
    }
}
E
